/** The event queue's limits (§15.6). */
export const EVENT_QUEUE_MAX_EVENTS = 8192;
export const EVENT_QUEUE_MAX_BYTES = 524288;
/** The main thread plays nothing for an event older than this many ticks (§15.6). */
export const EVENT_STALE_TICKS = 30;

/** An event's payload (§15.6), by type name. */
export type EventPayload =
  | ({ type: "action_failed" } & ActionFailedEvent)
  | ({ type: "flying_text" } & FlyingTextEvent)
  | ({ type: "entity_built" } & EntityBuiltEvent)
  | ({ type: "entity_mined" } & EntityMinedEvent)
  | ({ type: "entity_rotated" } & EntityRotatedEvent)
  | ({ type: "item_crafted" } & ItemCraftedEvent)
  | ({ type: "research_completed" } & ResearchCompletedEvent)
  | ({ type: "milestone" } & MilestoneEvent)
  | ({ type: "alert_raised" } & AlertRaisedEvent)
  | ({ type: "player_joined" })
  | ({ type: "player_left" })
  | ({ type: "input_fenced" })
  | ({ type: "loop_closed" })
  | ({ type: "victory" });
export type EventName = EventPayload['type'];
export const EVENT_IDS: Readonly<Record<EventName, number>> = {
  action_failed: 1,
  flying_text: 2,
  entity_built: 3,
  entity_mined: 4,
  entity_rotated: 5,
  item_crafted: 6,
  research_completed: 7,
  milestone: 8,
  alert_raised: 9,
  player_joined: 10,
  player_left: 11,
  input_fenced: 12,
  loop_closed: 13,
  victory: 14,
};
const EVENT_BY_ID: ReadonlyMap<number, EventName> = new Map([[1, "action_failed"], [2, "flying_text"], [3, "entity_built"], [4, "entity_mined"], [5, "entity_rotated"], [6, "item_crafted"], [7, "research_completed"], [8, "milestone"], [9, "alert_raised"], [10, "player_joined"], [11, "player_left"], [12, "input_fenced"], [13, "loop_closed"], [14, "victory"]]);
const EVENT_SIZE: Readonly<Record<EventName, number>> = {
  action_failed: 16,
  flying_text: 20,
  entity_built: 16,
  entity_mined: 16,
  entity_rotated: 16,
  item_crafted: 4,
  research_completed: 4,
  milestone: 2,
  alert_raised: 16,
  player_joined: 0,
  player_left: 0,
  input_fenced: 0,
  loop_closed: 0,
  victory: 0,
};

/** The event header without its type and length (they come from the payload). */
export type EventMeta = Omit<EventHeader, 'type' | 'len'>;

/** Decodes the payload of an event of type id `type`, which must fill `bytes` exactly. */
export function decodeEventPayload(type: number, bytes: Uint8Array): EventPayload {
  const name = EVENT_BY_ID.get(type);
  if (name === undefined) throw new DecodeError('unknown_type', 'EventPayload', 0);
  const r = new Reader(bytes);
  let p: EventPayload;
  switch (name) {
    case "action_failed":
      p = { type: name, ...ActionFailedEventCodec.read(r) };
      break;
    case "flying_text":
      p = { type: name, ...FlyingTextEventCodec.read(r) };
      break;
    case "entity_built":
      p = { type: name, ...EntityBuiltEventCodec.read(r) };
      break;
    case "entity_mined":
      p = { type: name, ...EntityMinedEventCodec.read(r) };
      break;
    case "entity_rotated":
      p = { type: name, ...EntityRotatedEventCodec.read(r) };
      break;
    case "item_crafted":
      p = { type: name, ...ItemCraftedEventCodec.read(r) };
      break;
    case "research_completed":
      p = { type: name, ...ResearchCompletedEventCodec.read(r) };
      break;
    case "milestone":
      p = { type: name, ...MilestoneEventCodec.read(r) };
      break;
    case "alert_raised":
      p = { type: name, ...AlertRaisedEventCodec.read(r) };
      break;
    case "player_joined":
      p = { type: name };
      break;
    case "player_left":
      p = { type: name };
      break;
    case "input_fenced":
      p = { type: name };
      break;
    case "loop_closed":
      p = { type: name };
      break;
    case "victory":
      p = { type: name };
      break;
  }
  r.finish('EventPayload');
  return p;
}

export function encodeEventPayload(w: Writer, p: EventPayload): void {
  switch (p.type) {
    case "action_failed":
      ActionFailedEventCodec.write(w, p);
      return;
    case "flying_text":
      FlyingTextEventCodec.write(w, p);
      return;
    case "entity_built":
      EntityBuiltEventCodec.write(w, p);
      return;
    case "entity_mined":
      EntityMinedEventCodec.write(w, p);
      return;
    case "entity_rotated":
      EntityRotatedEventCodec.write(w, p);
      return;
    case "item_crafted":
      ItemCraftedEventCodec.write(w, p);
      return;
    case "research_completed":
      ResearchCompletedEventCodec.write(w, p);
      return;
    case "milestone":
      MilestoneEventCodec.write(w, p);
      return;
    case "alert_raised":
      AlertRaisedEventCodec.write(w, p);
      return;
    case "player_joined":
      return;
    case "player_left":
      return;
    case "input_fenced":
      return;
    case "loop_closed":
      return;
    case "victory":
      return;
  }
}

/** Writes one EVENTS record (§15.6): the header, the payload, zero padding to 4. */
export function writeEvent(w: Writer, meta: EventMeta, p: EventPayload): void {
  const id = EVENT_IDS[p.type];
  if (id === undefined) throw new EncodeError('unknown_type', 'EventHeader.type');
  const start = w.pos;
  EventHeaderCodec.write(w, { ...meta, type: id, len: EVENT_SIZE[p.type] });
  encodeEventPayload(w, p);
  w.pad(start, 4);
}

/** Reads one EVENTS record: the header, the payload (exactly `len` bytes of its type) and the padding. */
export function readEvent(r: Reader): { header: EventHeader; payload: EventPayload } {
  const start = r.pos;
  const header = EventHeaderCodec.read(r, 'EventHeader');
  const body = r.take(header.len, 'EventRecord.payload');
  let payload: EventPayload;
  try {
    payload = decodeEventPayload(header.type, body);
  } catch (e) {
    if (e instanceof DecodeError) throw new DecodeError(e.kind, e.field, e.at + start + 16);
    throw e;
  }
  r.pad(start, 4, 'EventRecord.padding');
  return { header, payload };
}

/** The records of an EVENTS section. */
export function readEvents(bytes: Uint8Array, count: number): { header: EventHeader; payload: EventPayload }[] {
  const r = new Reader(bytes);
  const out: { header: EventHeader; payload: EventPayload }[] = [];
  for (let i = 0; i < count; i++) out.push(readEvent(r));
  r.finish('EVENTS');
  return out;
}

export function dumpEvent(d: Dump, p: EventPayload): void {
  d.line('type', p.type);
  switch (p.type) {
    case "action_failed":
      ActionFailedEventCodec.dump(d, p, '');
      return;
    case "flying_text":
      FlyingTextEventCodec.dump(d, p, '');
      return;
    case "entity_built":
      EntityBuiltEventCodec.dump(d, p, '');
      return;
    case "entity_mined":
      EntityMinedEventCodec.dump(d, p, '');
      return;
    case "entity_rotated":
      EntityRotatedEventCodec.dump(d, p, '');
      return;
    case "item_crafted":
      ItemCraftedEventCodec.dump(d, p, '');
      return;
    case "research_completed":
      ResearchCompletedEventCodec.dump(d, p, '');
      return;
    case "milestone":
      MilestoneEventCodec.dump(d, p, '');
      return;
    case "alert_raised":
      AlertRaisedEventCodec.dump(d, p, '');
      return;
    case "player_joined":
      return;
    case "player_left":
      return;
    case "input_fenced":
      return;
    case "loop_closed":
      return;
    case "victory":
      return;
  }
}
